import{_ as a,o as t,c as i,a3 as n}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"Always patch ha-card","description":"Experimentelle Option, um ha-card immer zu patchen.","frontmatter":{"title":"Always patch ha-card","description":"Experimentelle Option, um ha-card immer zu patchen."},"headers":[],"relativePath":"projects/uix/extras/always-patch-ha-card.md","filePath":"projects/uix/extras/always-patch-ha-card.md","lastUpdated":1792754181000}'),r={name:"projects/uix/extras/always-patch-ha-card.md"};function o(s,e,d,c,l,h){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="always-patch-ha-card" tabindex="-1">Always patch ha-card <a class="header-anchor" href="#always-patch-ha-card" aria-label="Permalink to &quot;Always patch ha-card&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Verfügbar ab UIX 8.2.0-beta.1</p><p>Diese Option ist experimentell.</p></div><p>Standardmäßig patcht UIX <code>ha-card</code> nicht, wenn in der ersten Frontend- oder Custom-Komponente im übergeordneten DOM-Baum keine Kartenkonfiguration gefunden wird. Diese experimentelle Option erlaubt, <code>ha-card</code> immer zu patchen, damit die Theme-Variable <code>uix-card(-yaml)</code> angewendet werden kann. <code>ha-card</code> ohne Konfiguration kann zum Beispiel in Konfigurations- oder Custom Panels vorkommen.</p><p>Wenn <code>ha-card</code> ohne Konfiguration gepatcht wird, fügt UIX die Klasse <code>type-generic-card</code> zu <code>ha-card</code> hinzu.</p><h2 id="einstellung-uber-die-integrations-ui" tabindex="-1">Einstellung über die Integrations-UI <a class="header-anchor" href="#einstellung-uber-die-integrations-ui" aria-label="Permalink to &quot;Einstellung über die Integrations-UI&quot;">​</a></h2><p>Die Option ist standardmäßig <strong>nicht gesetzt</strong>.</p><ol><li>In Home Assistant zu <strong>Settings -&gt; Devices &amp; Services -&gt; UI eXtension -&gt; Configure</strong> gehen.</li><li><strong>Experimental settings</strong> im Menü wählen.</li><li><strong>Always patch ha-card</strong> aktivieren.</li><li>Speichern.</li></ol><p>Die Einstellung ist sofort für alle verbundenen Browser-Sessions verfügbar. Ein Neuladen der Seite kann nötig sein, damit die Änderung sichtbar wird.</p><h2 id="verhalten-bei-aktivierter-option" tabindex="-1">Verhalten bei aktivierter Option <a class="header-anchor" href="#verhalten-bei-aktivierter-option" aria-label="Permalink to &quot;Verhalten bei aktivierter Option&quot;">​</a></h2><ul><li><code>ha-card</code> wird immer gepatcht, auch wenn keine Kartenkonfiguration verfügbar ist.</li><li>Wird <code>ha-card</code> auf diese Weise gepatcht, erhält es die Klasse <code>type-generic-card</code>.</li></ul>',10)])])}const g=a(r,[["render",o]]);export{u as __pageData,g as default};
